<?php

declare(strict_types=1);

namespace Strapi\Utils\Tests;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use Strapi\Utils\Yup;
use Strapi\Utils\Yup\TestContext;
use Strapi\Utils\Yup\Undefined;
use Strapi\Utils\Yup\Yup as Schema;
use Strapi\Utils\Yup\YupError;

/**
 * The yup facade (packages/core/utils/src/yup.ts) and the yup 0.32.9 port behind it.
 *
 * `testMatchesYupOracle` replays a table of schemas × values × options against results recorded
 * from the real yup@0.32.9 (with @strapi/utils' extensions and locale installed): for each case,
 * the validated value or the error message and formatted inner errors (`path`, `message`, `value`).
 * Options: `{strict: false, abortEarly: false}`, `{strict: true, abortEarly: false}` and `{}`
 * (yup's defaults: non-strict, abort early; only the outcome and message are recorded).
 * JSON markers: "__undefined__" = undefined, "__NaN__" = NaN, "__Infinity__" = Infinity.
 */
final class YupTest extends TestCase
{
    /** @return array<string, \Closure(): Schema> the same schemas as the oracle script, by id */
    private static function schemas(): array
    {
        $U = Undefined::value();

        return [
            // mixed
            'mixed_required' => static fn () => Yup::mixed()->required(),
            'mixed_notNil' => static fn () => Yup::mixed()->notNil(),
            'mixed_notNull' => static fn () => Yup::mixed()->notNull(),
            'mixed_defined' => static fn () => Yup::mixed()->defined(),
            'mixed_oneOf' => static fn () => Yup::mixed()->oneOf(['a', 1, null]),
            'mixed_notOneOf' => static fn () => Yup::mixed()->notOneOf(['a', 1]),
            'mixed_nullable_oneOf' => static fn () => Yup::mixed()->nullable()->oneOf(['a']),
            'mixed_isFunction' => static fn () => Yup::mixed()->isFunction(),
            'mixed_label' => static fn () => Yup::mixed()->label('My field')->required(),
            'mixed_test_falsy' => static fn () => Yup::mixed()->test('t', '${path} bad ${value}', static fn (mixed $v): bool => $v !== 'bad'),
            'mixed_test_default_msg' => static fn () => Yup::mixed()->test('t', static fn (mixed $v): bool => $v !== 'bad'),
            'mixed_test_createError' => static fn () => Yup::mixed()->test('t', 'unused', static fn (mixed $v, TestContext $ctx): bool|YupError => $v === 'bad' ? $ctx->createError(['path' => 'custom.path', 'message' => '${path} custom ${value}']) : true),
            'mixed_test_throw' => static fn () => Yup::mixed()->test('t', 'unused', static function (mixed $v, TestContext $ctx): bool {
                if ($v === 'bad') {
                    throw $ctx->createError(['message' => 'thrown']);
                }

                return true;
            }),
            'mixed_test_params' => static fn () => Yup::mixed()->test(['name' => 'p', 'message' => '${path} needs ${n}', 'params' => ['n' => 5], 'test' => static fn (): bool => false]),
            'mixed_test_exclusive' => static fn () => Yup::mixed()
                ->test(['name' => 'e', 'exclusive' => true, 'message' => 'first', 'test' => static fn (): bool => false])
                ->test(['name' => 'e', 'exclusive' => true, 'message' => 'second', 'test' => static fn (): bool => false]),
            'mixed_test_stacked' => static fn () => Yup::mixed()->test('s', 'first', static fn (): bool => false)->test('s', 'second', static fn (): bool => false),
            'mixed_notNil_twice' => static fn () => Yup::mixed()->notNil()->notNil('again'),
            'mixed_typeError' => static fn () => Yup::number()->typeError('must be a number!'),
            'mixed_message_fn' => static fn () => Yup::string()->min(3, static fn (array $p): string => "{$p['path']}:{$p['min']}:{$p['value']}"),
            'mixed_default' => static fn () => Yup::mixed()->default('d'),
            'mixed_default_fn' => static fn () => Yup::mixed()->default(static fn (): string => 'computed'),
            'mixed_transform' => static fn () => Yup::mixed()->transform(static fn (mixed $v): mixed => is_string($v) ? $v . '!' : $v),
            'mixed_concat' => static fn () => Yup::mixed()->notNull()->concat(Yup::string()->min(2)),
            'mixed_strip' => static fn () => Yup::object(['a' => Yup::string(), 'b' => Yup::string()->strip()]),

            // string
            'string_cast' => static fn () => Yup::string(),
            'string_nullable' => static fn () => Yup::string()->nullable(),
            'string_required' => static fn () => Yup::string()->required(),
            'string_min_max' => static fn () => Yup::string()->min(2)->max(4),
            'string_length' => static fn () => Yup::string()->length(3),
            'string_matches' => static fn () => Yup::string()->matches('/^[a-z]+$/'),
            'string_matches_exclude' => static fn () => Yup::string()->matches('/^[a-z]+$/', ['excludeEmptyString' => true, 'message' => 'only lowercase']),
            'string_matches_fn_msg' => static fn () => Yup::string()->matches('/^[a-z]([a-z|.|-]+)[a-z]$/', static fn (array $v): string => "{$v['path']}: The uid can only contain lowercase letters, dots and hyphens."),
            'string_email' => static fn () => Yup::string()->email(),
            'string_url' => static fn () => Yup::string()->url(),
            'string_uuid' => static fn () => Yup::string()->uuid(),
            'string_trim' => static fn () => Yup::string()->trim(),
            'string_lowercase' => static fn () => Yup::string()->lowercase(),
            'string_uppercase' => static fn () => Yup::string()->uppercase(),
            'string_email_lowercase' => static fn () => Yup::string()->email()->lowercase(),
            'string_ensure' => static fn () => Yup::string()->ensure(),
            'string_camel' => static fn () => Yup::string()->isCamelCase(),
            'string_kebab' => static fn () => Yup::string()->isKebabCase(),
            'string_oneOf_message' => static fn () => Yup::string()->oneOf(['a', 'b']),

            // number
            'number_cast' => static fn () => Yup::number(),
            'number_nullable' => static fn () => Yup::number()->nullable(),
            'number_integer' => static fn () => Yup::number()->integer(),
            'number_min_max' => static fn () => Yup::number()->min(1)->max(10),
            'number_more_less' => static fn () => Yup::number()->moreThan(1)->lessThan(10),
            'number_positive' => static fn () => Yup::number()->positive(),
            'number_negative' => static fn () => Yup::number()->negative(),
            'number_round' => static fn () => Yup::number()->round(),
            'number_round_floor' => static fn () => Yup::number()->round('floor'),
            'number_truncate' => static fn () => Yup::number()->truncate(),

            // boolean
            'boolean_cast' => static fn () => Yup::boolean(),
            'boolean_isTrue' => static fn () => Yup::boolean()->isTrue(),
            'boolean_isFalse' => static fn () => Yup::bool()->isFalse(),

            // array
            'array_cast' => static fn () => Yup::array(),
            'array_of' => static fn () => Yup::array()->of(Yup::number()),
            'array_ctor_of' => static fn () => Yup::array(Yup::string()->required()),
            'array_min_max' => static fn () => Yup::array()->min(1)->max(2),
            'array_length' => static fn () => Yup::array()->length(2),
            'array_required' => static fn () => Yup::array()->required(),
            'array_nested_paths' => static fn () => Yup::array()->of(Yup::object(['name' => Yup::string()->required(), 'n' => Yup::number()->max(3)])),
            'array_uniqueProperty' => static fn () => Yup::array()->of(Yup::object(['name' => Yup::string()]))->uniqueProperty('name', 'Duplicated name'),
            'array_ensure' => static fn () => Yup::array()->ensure(),
            'array_compact' => static fn () => Yup::array()->compact(),

            // object
            'object_basic' => static fn () => Yup::object(['name' => Yup::string()->required(), 'age' => Yup::number()]),
            'object_nullable_default_null' => static fn () => Yup::object(['x' => Yup::number()->min(0)->max(100)->required(), 'y' => Yup::number()->required()])->nullable()->default(null),
            'object_default_from_shape' => static fn () => Yup::object(['a' => Yup::string()->default('A'), 'b' => Yup::string(), 'c' => Yup::object(['d' => Yup::number()->default(1)])]),
            'object_required_undefined' => static fn () => Yup::object(['a' => Yup::string()])->required(),
            'object_empty_required' => static fn () => Yup::object()->required(),
            'object_noUnknown' => static fn () => Yup::object(['a' => Yup::string()])->noUnknown(),
            'object_noUnknown_msg' => static fn () => Yup::object(['a' => Yup::string()])->noUnknown('Unknown!'),
            'object_noUnknown_false' => static fn () => Yup::object(['a' => Yup::string()])->noUnknown(false),
            'object_unknown_strip' => static fn () => Yup::object(['a' => Yup::string()])->noUnknown(),
            'object_nested_errors' => static fn () => Yup::object([
                'name' => Yup::string()->required(),
                'price' => Yup::number()->integer()->required(),
                'info' => Yup::object(['desc' => Yup::string()->max(2), 'tags' => Yup::array()->of(Yup::string()->min(2))]),
            ]),
            'object_error_order' => static fn () => Yup::object(['zeta' => Yup::string()->required(), 'alpha' => Yup::string()->required(), 'name' => Yup::string()->required()]),
            'object_own_and_nested' => static fn () => Yup::object(['a' => Yup::string()->required()])->test('own', 'own failed', static fn (): bool => false),
            'object_dotted_key' => static fn () => Yup::object(['a.b' => Yup::string()->required()]),
            'object_shape_extend' => static fn () => Yup::object(['a' => Yup::string()])->shape(['b' => Yup::number()->required()]),
            'object_concat' => static fn () => Yup::object(['a' => Yup::string()->required()])->concat(Yup::object(['b' => Yup::string()->required()])),
            'object_pick_omit' => static fn () => Yup::object(['a' => Yup::string()->required(), 'b' => Yup::string()->required(), 'c' => Yup::string()->required()])->pick(['a', 'b'])->omit(['b']),
            'object_when_is' => static fn () => Yup::object([
                'section' => Yup::string(),
                'plugin' => Yup::mixed()->when('section', ['is' => 'plugins', 'then' => Yup::string()->required(), 'otherwise' => Yup::mixed()->oneOf([$U], 'only for plugins')]),
            ]),
            'object_when_is_fn' => static fn () => Yup::object([
                'section' => Yup::string(),
                'sub' => Yup::mixed()->when('section', [
                    'is' => static fn (mixed $s): bool => in_array($s, ['a', 'b'], true),
                    'then' => Yup::string()->required(),
                    'otherwise' => Yup::mixed()->test('t', 'sub only for a/b', static fn (mixed $v): bool => $v instanceof Undefined),
                ]),
            ]),
            'object_when_fn' => static fn () => Yup::object([
                'password' => Yup::string(),
                'currentPassword' => Yup::string()->when('password', static fn (mixed $password, Schema $schema): Schema => !($password instanceof Undefined) ? $schema->required() : $schema)->notNull(),
            ]),
            'object_when_replace' => static fn () => Yup::object([
                'enum' => Yup::array()->of(Yup::string()),
                'default' => Yup::string()->when('enum', static fn (mixed $enumVal): Schema => Yup::string()->oneOf(is_array($enumVal) ? array_values($enumVal) : [])),
            ]),
            'object_when_cast_order' => static fn () => Yup::object(['b' => Yup::number()->when('a', ['is' => 5, 'then' => Yup::number()->max(1)]), 'a' => Yup::number()]),
            'object_parent' => static fn () => Yup::object([
                'minLength' => Yup::number(),
                'maxLength' => Yup::number()->test([
                    'name' => 'gt',
                    'message' => 'maxLength must be greater or equal to minLength',
                    'test' => static function (mixed $value, TestContext $ctx): bool {
                        $minLength = is_array($ctx->parent) && array_key_exists('minLength', $ctx->parent) ? $ctx->parent['minLength'] : Undefined::value();

                        return !(!($minLength instanceof Undefined) && !($value instanceof Undefined) && $value < $minLength);
                    },
                ]),
            ]),
            'object_options_parent' => static fn () => Yup::object([
                'action' => Yup::string(),
                'subject' => Yup::string()->nullable()->test('s', 'Invalid subject submitted', static fn (mixed $subject, TestContext $ctx): bool => ($ctx->options['parent']['action'] ?? null) === 'read' || Schema::isAbsent($subject)),
            ]),
            'object_onlyContainsFunctions' => static fn () => Yup::object()->onlyContainsFunctions(),
            'object_strict_flag' => static fn () => Yup::object(['a' => Yup::number()])->strict(),
            'object_field_strict' => static fn () => Yup::object(['a' => Yup::number()->strict(), 'b' => Yup::number()]),
            'object_lazy' => static fn () => Yup::object([
                'v' => Yup::lazy(static fn (mixed $v): Schema => match (true) {
                    is_array($v) && array_is_list($v) => Yup::array()->of(Yup::string())->min(1)->max(2),
                    is_string($v) => Yup::string()->required(),
                    default => Yup::object(['action' => Yup::string()->required()]),
                }),
            ]),

            // ref
            'ref_min' => static fn () => Yup::object(['min' => Yup::number(), 'max' => Yup::number()->min(Yup::ref('min'))]),
            'ref_oneOf' => static fn () => Yup::object(['password' => Yup::string(), 'confirm' => Yup::string()->oneOf([Yup::ref('password')])]),

            // strapiID
            'strapiID' => static fn () => Yup::strapiID(),
            'strapiID_required' => static fn () => Yup::strapiID()->required(),
            'strapiID_nullable' => static fn () => Yup::strapiID()->nullable(),
            'strapiID_nullable_defined' => static fn () => Yup::strapiID()->nullable()->defined(),
            'strapiID_array' => static fn () => Yup::array()->of(Yup::strapiID())->min(1),
        ];
    }

