    /** @return iterable<string, array{string, mixed, array<string, mixed>, array<string, mixed>}> */
    public static function oracleCases(): iterable
    {
        /** @var array<string, list<array<string, mixed>>> $all */
        $all = json_decode(self::ORACLE, true, 512, JSON_THROW_ON_ERROR);
        foreach ($all as $id => $cases) {
            foreach ($cases as $i => $case) {
                $opts = $case['opts'] === [] ? 'defaults' : ($case['opts']['strict'] ? 'strict' : 'cast');
                yield "{$id} #{$i} ({$opts}) " . json_encode($case['input']) => [$id, self::decode($case['input']), $case['opts'], self::knownDivergences($case)];
            }
        }
    }

    /**
     * @param array<string, mixed> $opts
     * @param array<string, mixed> $expected
     */
    #[DataProvider('oracleCases')]
    public function testMatchesYupOracle(string $id, mixed $input, array $opts, array $expected): void
    {
        $schema = self::schemas()[$id]();

        try {
            $result = $schema->validateSync($input, $opts);
        } catch (YupError $e) {
            self::assertFalse($expected['ok'], "unexpected error: {$e->getMessage()}");
            self::assertSame($expected['message'], $e->getMessage());
            if (isset($expected['errors'])) {
                $errors = array_map(static fn (YupError $err): array => [
                    'path' => \Strapi\Utils\Primitives\Objects::toPath($err->path ?? ''),
                    'message' => $err->getMessage(),
                    'value' => self::encode($err->value),
                ], $e->inner !== [] ? $e->inner : [$e]);
                self::assertSame(self::canonical($expected['errors']), self::canonical($errors));
            }

            return;
        }

        self::assertTrue($expected['ok'], 'expected an error: ' . ($expected['message'] ?? ''));
        self::assertSame(self::canonical($expected['value']), self::canonical(self::encode($result)));
    }

    /**
     * Known, deliberate divergence: the `${values}` list of a oneOf/notOneOf message writes null as
     * "null" (yup's `Array.join` writes an empty string), as the entity validator's enumeration
     * message always has.
     *
     * @param array<string, mixed> $case
     * @return array<string, mixed>
     */
    private static function knownDivergences(array $case): array
    {
        $json = (string) json_encode($case);
        $json = str_replace('one of the following values: a, 1, "', 'one of the following values: a, 1, null"', $json);

        /** @var array<string, mixed> $fixed */
        $fixed = json_decode($json, true);

        return $fixed;
    }

    private static function decode(mixed $value): mixed
    {
        return match (true) {
            $value === '__undefined__' => Undefined::value(),
            $value === '__NaN__' => NAN,
            $value === '__Infinity__' => INF,
            is_array($value) => array_map(self::decode(...), $value),
            default => $value,
        };
    }

    private static function encode(mixed $value): mixed
    {
        return match (true) {
            $value instanceof Undefined => '__undefined__',
            is_float($value) && is_nan($value) => '__NaN__',
            $value === INF => '__Infinity__',
            is_float($value) && floor($value) === $value && abs($value) < PHP_INT_MAX => (int) $value,
            is_array($value) => array_map(self::encode(...), $value),
            default => $value,
        };
    }

    /**
     * Key order of JS objects is not compared (the port keeps the input's key order), and a key
     * holding undefined is a missing key (the port leaves such keys out, as JSON does).
     */
    private static function canonical(mixed $value): mixed
    {
        if (!is_array($value)) {
            return $value;
        }
        $value = array_map(self::canonical(...), $value);
        if (!array_is_list($value)) {
            $value = array_filter($value, static fn (mixed $v): bool => $v !== '__undefined__');
            ksort($value);
        }

        return $value;
    }

    public function testFacadeFactories(): void
    {
        self::assertInstanceOf(Schema::class, Yup::mixed());
        self::assertSame('mixed', Yup::mixed()->type());
        self::assertSame('string', Yup::string()->type());
        self::assertSame('number', Yup::number()->type());
        self::assertSame('boolean', Yup::boolean()->type());
        self::assertSame('boolean', Yup::bool()->type());
        self::assertSame('array', Yup::array()->type());
        self::assertSame('object', Yup::object()->type());
        self::assertSame('strapiID', Yup::strapiID()->type());
        self::assertSame('Ref(a.b)', (string) Yup::ref('a.b'));
        self::assertTrue(Yup::isSchema(Yup::lazy(static fn (): Schema => Yup::string())));
        self::assertFalse(Yup::isSchema('string'));
        self::assertSame(Undefined::value(), Yup::undefined());
        self::assertTrue(Yup::isValidationError(new YupError('x')));
    }

    public function testSchemasAreImmutable(): void
    {
        $base = Yup::string();
        $required = $base->required();

        self::assertTrue($base->isValid(Undefined::value()));
        self::assertFalse($required->isValid(Undefined::value()));
        self::assertSame('optional', $base->spec()['presence']);
        self::assertSame('required', $required->spec()['presence']);
    }

    public function testValidationErrorAggregatesInnerErrors(): void
    {
        $schema = Yup::object(['a' => Yup::string()->required(), 'b' => Yup::number()->min(2)]);

        try {
            $schema->validate(['b' => 1], ['abortEarly' => false]);
            self::fail('expected a YupError');
        } catch (YupError $e) {
            self::assertSame('ValidationError', $e->name);
            self::assertSame('2 errors occurred', $e->getMessage());
            self::assertSame(['a is a required field', 'b must be greater than or equal to 2'], $e->errors);
            self::assertSame(['a', 'b'], array_map(static fn (YupError $i): ?string => $i->path, $e->inner));
            self::assertSame(['required', 'min'], array_map(static fn (YupError $i): ?string => $i->type, $e->inner));
            self::assertSame(['min' => 2], array_intersect_key($e->inner[1]->params, ['min' => 1]));
        }
    }

    public function testUniquePropertyReportsEveryDuplicate(): void
    {
        $schema = Yup::object(['list' => Yup::array()->of(Yup::object(['name' => Yup::string()]))->uniqueProperty('name', 'name must be unique')]);

        try {
            $schema->validate(['list' => [['name' => 'a'], ['name' => 'b'], ['name' => 'a']]], ['abortEarly' => false]);
            self::fail('expected a YupError');
        } catch (YupError $e) {
            self::assertSame(['list[0].name', 'list[2].name'], array_map(static fn (YupError $i): ?string => $i->path, $e->inner));
            self::assertSame(['name must be unique', 'name must be unique'], $e->errors);
        }
    }

    public function testNotNilAndNotNullShareTheDefinedTestName(): void
    {
        // yup.ts registers both as a non-exclusive test named "defined"
        $schema = Yup::mixed()->notNull()->notNil();

        self::assertFalse($schema->isValid(null));
        self::assertFalse($schema->isValid(Undefined::value()));
        self::assertSame(['defined', 'defined'], array_map(static fn ($t): ?string => $t->name, $schema->tests()));
    }

    public function testIsFunctionAndOnlyContainsFunctionsAcceptClosures(): void
    {
        self::assertTrue(Yup::mixed()->isFunction()->isValid(static fn (): null => null));
        self::assertTrue(Yup::object()->onlyContainsFunctions()->isValid(['register' => static fn (): null => null, 'bootstrap' => static fn (): null => null]));
        self::assertFalse(Yup::object()->onlyContainsFunctions()->isValid(['register' => static fn (): null => null, 'x' => 1]));
    }

    public function testCastAssertsTheType(): void
    {
        self::assertSame(5, Yup::number()->cast('5'));
        self::assertSame(['a' => 1], Yup::object(['a' => Yup::number()])->cast(['a' => '1']));

        $this->expectException(\TypeError::class);
        $this->expectExceptionMessage('The value of field could not be cast to a value that satisfies the schema type: "number".');
        Yup::number()->cast('abc');
    }

    public function testNonValidationExceptionsPropagate(): void
    {
        $schema = Yup::string()->test('boom', 'unused', static function (): bool {
            throw new \LogicException('boom');
        });

        $this->expectException(\LogicException::class);
        $schema->validate('x');
    }

    public function testTestRequiresAFunction(): void
    {
        $this->expectException(\TypeError::class);
        Yup::mixed()->test(['name' => 'x']);
    }

    public function testWhenRequiresIsAndABranch(): void
    {
        $this->expectException(\TypeError::class);
        Yup::mixed()->when('a', ['then' => Yup::string()]);
    }

    public function testConcatRejectsDifferentTypes(): void
    {
        $this->expectException(\TypeError::class);
        Yup::string()->concat(Yup::number());
    }

    public function testDescribe(): void
    {
        $description = Yup::object(['ids' => Yup::array()->of(Yup::strapiID())->min(1)->label('IDs')])->noUnknown()->describe();

        self::assertSame('object', $description['type']);
        self::assertSame([['name' => 'noUnknown', 'params' => null]], $description['tests']);
        self::assertSame('IDs', $description['fields']['ids']['label']);
        self::assertSame([['name' => 'min', 'params' => ['min' => 1]]], $description['fields']['ids']['tests']);
        self::assertSame('strapiID', $description['fields']['ids']['innerType']['type']);
    }

    public function testContextRefsAndWhen(): void
    {
        $schema = Yup::object([
            'name' => Yup::string()->when('$isAdmin', ['is' => true, 'then' => Yup::string()->required()]),
        ]);

        self::assertTrue($schema->isValid([], ['context' => ['isAdmin' => false]]));
        self::assertFalse($schema->isValid([], ['context' => ['isAdmin' => true]]));
    }

    public function testLazyBuilderReceivesUndefinedForMissingKeys(): void
    {
        $seen = [];
        $schema = Yup::object(['a' => Yup::lazy(static function (mixed $value) use (&$seen): Schema {
            $seen[] = $value;

            return Yup::mixed();
        })]);
        $schema->validate([], ['strict' => true]);

        self::assertSame([Undefined::value()], $seen);
    }
}
